#include <stdio.h>
#include <signal.h>
#include <stdlib.h>

void handle_signal(int sig) {
  printf("Signal %d received\n", sig);
  exit(1);
}

int main() {
  if (signal(SIGINT, handle_signal) == SIG_ERR) {
    perror("signal");
    exit(1);
  }
  printf("Press Ctrl+C to send a SIGINT signal...\n");
  while (1) {
    // Keep the program running until a signal is received
  }
  return 0;
}
